begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select ok(not public,'bucket de membros não é público') from storage.buckets where id='member-private';
select is(file_size_limit,4194304::bigint,'bucket limita arquivos a 4 MB') from storage.buckets where id='member-private';
select ok(not has_function_privilege('anon','private.member_file_allowed(text,boolean)','EXECUTE'),'visitante não consulta autorização privada');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('aa000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','files-owner@example.test',now(),now(),now());
insert into public.organizations(id,name,slug,status) values('ba000000-0000-4000-8000-000000000001','Arquivos A','files-a','active'),('ba000000-0000-4000-8000-000000000002','Arquivos B','files-b','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('ca000000-0000-4000-8000-000000000001','ba000000-0000-4000-8000-000000000001','Sede arquivos','sede','headquarters');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) values('ba000000-0000-4000-8000-000000000001','aa000000-0000-4000-8000-000000000001','owner','active','ca000000-0000-4000-8000-000000000001');
insert into public.people(id,organization_id,unit_id,full_name) values('da000000-0000-4000-8000-000000000001','ba000000-0000-4000-8000-000000000001','ca000000-0000-4000-8000-000000000001','Pessoa sintética arquivos');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"aa000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select ok(private.member_file_allowed('ba000000-0000-4000-8000-000000000001/da000000-0000-4000-8000-000000000001/ea000000-0000-4000-8000-000000000001.pdf',true),'gestor envia para cadastro autorizado');
select ok(not private.member_file_allowed('ba000000-0000-4000-8000-000000000002/da000000-0000-4000-8000-000000000001/ea000000-0000-4000-8000-000000000001.pdf',true),'prefixo de outro ministério não transfere arquivo');
select ok(not private.member_file_allowed('../documento.pdf',true),'traversal não autoriza acesso');
select ok(not private.member_file_allowed('ba000000-0000-4000-8000-000000000001/da000000-0000-4000-8000-000000000001/x.svg',true),'extensão ativa não é autorizada');
reset role;
update public.organizations set status='suspended' where id='ba000000-0000-4000-8000-000000000001';
set local role authenticated;
select ok(not private.member_file_allowed('ba000000-0000-4000-8000-000000000001/da000000-0000-4000-8000-000000000001/ea000000-0000-4000-8000-000000000001.pdf',true),'ministério suspenso não envia arquivo');
reset role;
select * from finish();
rollback;
